import{_ as d,o,c as t,a3 as c}from"./chunks/framework.CwI_YTFT.js";const m=JSON.parse('{"title":"LFOs","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/lfos.md","filePath":"developers/commands/lfos.md"}'),a={name:"developers/commands/lfos.md"};function s(n,e,r,i,l,p){return o(),t("div",null,[...e[0]||(e[0]=[c(`<h1 id="lfos" tabindex="-1">LFOs <a class="header-anchor" href="#lfos" aria-label="Permalink to &quot;LFOs&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --loopback repl</span></span>
<span class="line"><span>s32&gt; lfo cfg get s32 2</span></span>
<span class="line"><span>s32&gt; lfo cfg set s32 2 wave=sine freq=3.75 enabled=on</span></span>
<span class="line"><span>s32&gt; lfo assign add 2 target=macro pot=4 macro=1 min=-0.25 max=0.25</span></span>
<span class="line"><span>s32&gt; lfo assign list</span></span>
<span class="line"><span>s32&gt; lfo assign remove 0</span></span></code></pre></div><p><code>DOMAIN</code> is <code>s32</code> (the S32&#39;s own <a href="/versions/v0.19.97/lfos/">LFOs</a>) or <code>cv16</code> (the CV16 module&#39;s). <code>INDEX</code> is the LFO, <code>0</code>–<code>15</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p><code>lfo cfg get DOMAIN INDEX</code> prints the LFO&#39;s settings, then its IN SNAPSHOT (<code>liveOwned=</code>) and ALLOW MORPH (<code>allowMorph=</code>) bits as hex masks. <code>lfo cfg set</code> never changes those bits. Use <a href="./snapshots#in-snapshot"><code>snapshot flags</code> and <code>snapshot parent</code></a>.</p><p><code>lfo cfg set DOMAIN INDEX HZ</code> sets the frequency and turns the LFO on.</p><p><code>lfo cfg set DOMAIN INDEX key=value …</code> changes only the keys you name. Values outside the LFO&#39;s range are refused.</p><table tabindex="0"><thead><tr><th>Key</th><th>S32</th><th>CV16</th></tr></thead><tbody><tr><td><code>enabled</code></td><td><code>on</code> / <code>off</code></td><td><code>on</code> / <code>off</code></td></tr><tr><td><code>wave</code></td><td>see below</td><td>same</td></tr><tr><td><code>freq</code></td><td>Hz</td><td>Hz</td></tr><tr><td><code>bpm</code></td><td>Clock division, used with <code>sync=on</code></td><td>same</td></tr><tr><td><code>sync</code></td><td><code>on</code> / <code>off</code></td><td><code>on</code> / <code>off</code></td></tr><tr><td><code>phase</code></td><td>Degrees</td><td>Degrees</td></tr><tr><td><code>offset</code></td><td>yes</td><td>yes</td></tr><tr><td><code>amp</code></td><td><code>0</code>–<code>1</code></td><td>—</td></tr><tr><td><code>min</code> / <code>max</code></td><td>yes</td><td>—</td></tr><tr><td><code>depth</code></td><td>—</td><td><code>0</code>–<code>1</code></td></tr></tbody></table><p>Waves: <code>sine</code>, <code>triangle</code>, <code>square</code>, <code>saw</code>, <code>fold</code>, <code>s-h</code>, <code>exponential</code>, <code>stepped</code>, <code>double-sine</code>, <code>rev-saw</code>, <code>bell</code>, <code>double-triangle</code>, <code>smooth-random</code>, <code>trapezoid</code>, <code>pump</code>, <code>rounded-square</code>, <code>half-sine</code>.</p><h2 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to &quot;Assignments&quot;">​</a></h2><p><code>lfo assign add LFO target=… …</code> adds a row. <code>lfo assign set ROW LFO target=… …</code> rewrites one. <code>lfo assign remove ROW</code> deletes one. <code>lfo assign list</code> shows the row numbers.</p><table tabindex="0"><thead><tr><th><code>target=</code></th><th>Moves</th><th>Address</th><th><code>param=</code></th></tr></thead><tbody><tr><td><code>device</code></td><td>A rack device parameter</td><td><code>rack=ID device=ID</code> (ids from <code>rack list</code> / <code>device list</code>)</td><td>Parameter name (<code>bypass</code>, <code>rate</code>, <code>gate</code>, …) or number</td></tr><tr><td><code>lfo</code></td><td>Another LFO in the same domain</td><td><code>targetLfo=INDEX</code></td><td>LFO parameter (<code>amplitude</code>, <code>frequency</code>, <code>phase</code>, …)</td></tr><tr><td><code>macro</code></td><td>A knob macro</td><td><code>pot=KNOB macro=MACRO</code></td><td>—</td></tr></tbody></table><p>An LFO can&#39;t modulate itself, an LFO in the other domain, or close a loop of LFOs (1 → 2 → 1). Those rows are refused.</p><h3 id="range" tabindex="-1">Range <a class="header-anchor" href="#range" aria-label="Permalink to &quot;Range&quot;">​</a></h3><p>For <code>device</code> and <code>lfo</code> targets, <code>min</code> and <code>max</code> are values in the target&#39;s own range. Values outside it are clamped to the edge. On S32 targets <code>min</code> above <code>max</code> runs the sweep the other way. A CV16 LFO-to-LFO row refuses that.</p><p>For <code>macro</code> targets, <code>min</code> and <code>max</code> are the BELOW and ABOVE window around the knob, as fractions of the macro&#39;s range from <code>-1</code> to <code>1</code>. The default is <code>-0.5</code> / <code>0.5</code>. <code>min=0 max=0.4</code> only rises above the knob. Capability bit <code>1024</code> in <code>hello</code> means the firmware uses this window.</p>`,16)])])}const f=d(a,[["render",s]]);export{m as __pageData,f as default};
